import{z as p,x as B,o as r,c as A,q as o,j as s,D as E,d as t,s as l,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"物理时钟与漂移","description":"","frontmatter":{"title":"物理时钟与漂移","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clock-drift.md","filePath":"cs/clock-drift.md","lastUpdated":1791063341000}'),d={name:"cs/clock-drift.md"};function m(C,a,T,c,D,h){const i=B("Mermaid");return r(),A("div",null,[a[2]||(a[2]=o('<h1 id="物理时钟与漂移" tabindex="-1">物理时钟与漂移 <a class="header-anchor" href="#物理时钟与漂移" aria-label="Permalink to &quot;物理时钟与漂移&quot;">​</a></h1><div class="epigraph"><p>石英有漂移，NTP 把误差收到毫秒量级，仍不是全局同一时刻。用物理时间当「先后」必须声明误差界，否则会读出假因果。</p><footer>—— 据 Cristian, Probabilistic Clock Synchronization, Distributed Computing 1989；Mills, Network Time Protocol；Lamport, Time, Clocks 整理</footer></div><p>上一课<a href="/cs/sync-async-model">同步与异步</a>把延迟上界当成模型参数。实现上人们拿出机器上的时钟去近似「现在」。缺口是<strong>漂移与误差</strong>：本地钟不是 DLS 里的全局轮次。本课不重做部分同步定义，也不提前讲向量时钟。后课逻辑时钟正是因为物理钟不够格才引入的。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每台机器有硬件振荡器，频率相对真实时间有漂移率 \\(\\rho\\)（规格常给 \\(\\pm 10^{-4}\\) 到更好的 TCXO）。即使某一时刻对准，误差以 \\(\\rho\\) 增长。网络对时（Cristian：问服务器、用往返折半；NTP：多层 stratum、滤波）把误差压到一个区间 \\([C(t)-\\varepsilon, C(t)+\\varepsilon]\\)，不是一个点。<span class="marginnote">漂移率 \\(\\rho\\) 翻译过来就是「钟走快或走慢的比例」。数字实例：\\(\\rho = 10^{-4}\\) 意味着每 1 秒只偏 0.1 毫秒，看着很小；但误差会累积，一天 86400 秒乘下来约 8.6 秒——所以对准一次管不了多久，必须周期性地重新对时。</span></p><p>缺口：若 \\(\\varepsilon\\) 大于事件间隔，比较两台机器的时间戳<strong>不能</strong>得到 happened-before。Google 后来用 TrueTime 把 \\(\\varepsilon\\) 暴露成 API——那是后课地理复制的附录直觉，本课只要：物理钟给出的是区间，不是全序。</p><p><span class="marginnote">Lamport 1978 开篇就指出物理钟同步的限度，然后改用逻辑钟。Mills 的 NTP 是工程上把 \\(\\varepsilon\\) 做小，不是把限度取消。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Cristian：客户端测 RTT，设服务器时刻为 \\(T_s\\)，本地置为 \\(T_s+\\mathrm{RTT}/2\\)，误差不超过 \\(\\mathrm{RTT}/2\\)。NTP 用多次采样压异常延迟。伯克利算法（Gusella–Zatti）在无外部标准时做内部平均，去掉漂移过大的outlier。单调时钟（<code>CLOCK_MONOTONIC</code>）避免 NTP 回拨把超时算负；墙钟仍会跳。</p><p><span class="marginnote">直觉类比 Cristian 的折半：你问台北 101 的报时钟「现在几点」，听到回答时已过了一些时间，于是把「报出的时刻」加上「一半的往返耗时」当现在——等于假设去程和回程一样长。数字实例：RTT 测得 20 ms，就认为请求走了 10 ms，误差上界是 10 ms；若网络单边堵车，这个假设就歪了，NTP 因此要多次采样去掉异常值。</span></p>',10)),(r(),s(n,null,{default:E(()=>[l(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20OSC%5B%22%E6%8C%AF%E8%8D%A1%E5%99%A8%22%5D%20--%3E%20DRIFT%5B%22%E6%BC%82%E7%A7%BB%20%CF%81%22%5D%0A%20%20NTP%5B%22NTP%20%2F%20Cristian%22%5D%20--%3E%20EPS%5B%22%E8%AF%AF%E5%B7%AE%E5%8C%BA%E9%97%B4%20%CE%B5%22%5D%0A%20%20DRIFT%20--%3E%20EPS%0A%20%20EPS%20--%3E%20CMP%5B%22%E8%B7%A8%E6%9C%BA%E6%AF%94%E8%BE%83%E9%A1%BB%20%7C%CE%94t%7C%20%3E%202%CE%B5%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[t("租约、失败检测会用到本地超时；那些超时应走单调钟，不要走可回拨的墙钟。"),e("span",{class:"marginnote"},"常见误区：初学者容易以为 NTP 会把钟「悄悄拨准」，墙钟随便用。实际上对时可能阶跃跳变甚至往回拨——你设的 30 秒超时可能瞬间变成「还剩 60 秒」或「早就超了」。单调钟只前进不回退，专为「测时间间隔」而生；「现在是几点」才用墙钟。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"同步模型里的 \\(\\Delta\\) 是消息延迟；本课的 \\(\\varepsilon\\) 是时钟读数误差。二者独立：延迟界小并不自动让钟准。用时间戳排序必须满足 \\(|C_i(e)-C_j(f)|\\gt 2\\varepsilon\\) 才能下结论，否则只能说「分不清」。Spanner 的 commit wait 就是等 \\(\\varepsilon\\) 过去再对外可见——机制在后课，本课只准备 \\(\\varepsilon\\) 这个符号。",-1)),(r(),s(n,null,{default:E(()=>[l(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20TS%5B%22%E6%8B%BF%E5%88%B0%E4%B8%A4%E5%8F%B0%E6%9C%BA%E5%99%A8%E7%9A%84%E4%BA%8B%E4%BB%B6%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%20--%3E%20D%7B%22%E4%B8%A4%E4%B8%AA%E8%AF%AF%E5%B7%AE%E5%8C%BA%E9%97%B4%E6%98%AF%E5%90%A6%E9%87%8D%E5%8F%A0%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%22%E4%B8%8D%E9%87%8D%E5%8F%A0%22%7C%20OK%5B%22%E5%8F%AF%E4%B8%8B%E7%BB%93%E8%AE%BA%EF%BC%9A%E5%8C%BA%E9%97%B4%E9%9D%A0%E5%89%8D%E7%9A%84%E7%A1%AE%E5%AE%9E%E5%85%88%E5%8F%91%E7%94%9F%22%5D%0A%20%20D%20--%3E%7C%22%E9%87%8D%E5%8F%A0%22%7C%20NO%5B%22%E5%88%86%E4%B8%8D%E6%B8%85%E5%85%88%E5%90%8E%EF%BC%8C%E4%B8%8D%E5%BE%97%E8%A3%85%E4%BD%9C%E6%9C%89%E5%9B%A0%E6%9E%9C%22%5D%0A%20%20NO%20--%3E%20WAIT%5B%22%E7%AD%89%20%CE%B5%20%E8%BF%87%E5%8E%BB%E5%86%8D%E5%AF%B9%E5%A4%96%E5%8F%AF%E8%A7%81%EF%BC%88commit%20wait%EF%BC%89%22%5D%0A%20%20NO%20--%3E%20LC%5B%22%E6%88%96%E6%94%B9%E7%94%A8%E5%90%8E%E8%AF%BE%E7%9A%84%E9%80%BB%E8%BE%91%E9%92%9F%E8%AE%B0%E5%9B%A0%E6%9E%9C%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">这张图回答「什么时候敢凭时间戳下因果结论」。初学者容易以为「时间戳大的就是后发生」，实际上两台机器的钟各带 \\(\\pm\\varepsilon\\) 的误差，区间一重叠，先后就判不出来——这时硬排序读出来的是假因果。</span></p><p>漂移校正：线性补偿（测得频率偏差后调 skew）比反复硬跳更平滑。leap second 是 UTC 的政治，对单调钟无关，对墙钟日志是坑。</p><p>本课不把 GPS、原子钟当数据中心标配；多数服务仍活在 NTP 的毫秒到几十毫秒误差里。也不把「时钟」写成金融交易所的撮合时间——那是另一栏。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不定义 Lamport 时间戳，不写向量。不把 NTP 协议状态机展开。后课默认：跨节点比较墙钟必须带误差；因果顺序用逻辑钟；超时用单调本地钟。部分同步的 GST 不是 NTP 同步完成时刻。</p><p>物理钟近似真实时间，逻辑钟不试图近似真实时间。下一课从 happened-before 开始，不再假装有全局 \\(t\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>漂移使对准后的钟再分开；对时给出误差区间 \\(\\varepsilon\\)。</li><li>跨机时间戳比较要 \\(|Δt|\\gt 2\\varepsilon\\)，否则无先后。</li><li>超时用单调钟；墙钟会回拨。</li><li>出处：Cristian, 1989；Mills NTP；Lamport, 1978。</li></ul>',8))])}const f=p(d,[["render",m]]);export{F as __pageData,f as default};
